import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  boolean,
  check,
  index,
  integer,
  jsonb,
  text,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import {
  questionCognitiveLevels,
  questionDifficulties,
  questionPaperLanguages,
  questionPaperStatuses,
  questionSources,
  questionStatuses,
  questionTypes,
} from '@takhti/contracts';
import { baseColumns, branchIdColumn } from '../../kernel/base-columns';
import {
  dateStr,
  decimal,
  enumText,
  live,
  nonNegative,
  positive,
  timestamptz,
} from '../../kernel/columns';
import { defineTable } from '../../kernel/define-table';
import { customPolicy } from '../../kernel/policies';
import { gradeSubjects } from '../academics/academics.table';
import { profiles } from '../identity/identity.table';
import { boards } from '../setup/setup.table';
import { generatedDocuments } from '../shared/files.table';
import { staff } from '../staff/staff.table';
import { learningOutcomes, syllabusUnits } from '../syllabus/syllabus.table';

/* The tables of M19 · Question bank and papers. */

export const questions = defineTable(
  'questions',
  { module: 'M19', scope: 'org' },
  {
    ...baseColumns,
    gradeSubjectId: uuid()
      .references((): AnyPgColumn => gradeSubjects.id)
      .notNull(),
    unitId: uuid().references((): AnyPgColumn => syllabusUnits.id),
    outcomeId: uuid().references((): AnyPgColumn => learningOutcomes.id),
    type: enumText(questionTypes).notNull(),
    /** rich text; equations as LaTeX */
    text: text().notNull(),
    textUr: text(),
    /** `{ key, text, textUr? }`; required for `mcq` and `match` */
    options: jsonb().notNull().default([]),
    /** the key or a model answer */
    answer: jsonb(),
    markingScheme: text(),
    marks: decimal(5, 2).notNull(),
    difficulty: enumText(questionDifficulties).notNull().default('medium'),
    cognitiveLevel: enumText(questionCognitiveLevels).notNull().default('understanding'),
    source: enumText(questionSources).notNull().default('written'),
    /** "BISE Lahore, Annual 2024" */
    sourceNote: text(),
    status: enumText(questionStatuses).notNull().default('draft'),
    reviewedBy: uuid().references((): AnyPgColumn => profiles.id),
    reviewedAt: timestamptz(),
    createdByStaffId: uuid().references((): AnyPgColumn => staff.id),
    timesUsed: integer().notNull().default(0),
    lastUsedOn: dateStr(),
  },
  (t) => [
    check(
      'questions_options_needed',
      sql`${t.type} not in ('mcq', 'match') or ${t.options} <> '[]'::jsonb`,
    ),
    positive('questions', t.marks),
    nonNegative('questions', t.timesUsed),
    index('questions_grade_subject_unit_type_status_idx').on(
      t.orgId,
      t.gradeSubjectId,
      t.unitId,
      t.type,
      t.status,
    ),
    index('questions_search').using('gin', sql`to_tsvector('simple', coalesce(${t.text}, ''))`),
  ],
);

/** A paper pattern: sections, question types, counts and marks. */
export const paperBlueprints = defineTable(
  'paper_blueprints',
  { module: 'M19', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    /** empty for a pattern reusable across subjects */
    gradeSubjectId: uuid().references((): AnyPgColumn => gradeSubjects.id),
    boardId: uuid().references((): AnyPgColumn => boards.id),
    totalMarks: decimal(6, 2).notNull(),
    durationMinutes: integer().notNull(),
    /** `{ title, instructions?, type, count, attempt?, marksEach, difficulty?: { easy, medium, hard } }[]` */
    sections: jsonb().notNull(),
    /** `{ unitId, percent }` */
    unitWeights: jsonb().notNull().default([]),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    positive('paper_blueprints', t.totalMarks),
    positive('paper_blueprints', t.durationMinutes),
    uniqueIndex('paper_blueprints_name_uq').on(t.orgId, t.name).where(live(t)),
  ],
);

export const questionPapers = defineTable(
  'question_papers',
  { module: 'M19', scope: 'branch', custom: true },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    gradeSubjectId: uuid()
      .references((): AnyPgColumn => gradeSubjects.id)
      .notNull(),
    blueprintId: uuid().references((): AnyPgColumn => paperBlueprints.id),
    title: text().notNull(),
    /** "A", "B" */
    setLabel: text(),
    totalMarks: decimal(6, 2).notNull(),
    durationMinutes: integer().notNull(),
    instructions: text(),
    language: enumText(questionPaperLanguages).notNull().default('en'),
    status: enumText(questionPaperStatuses).notNull().default('draft'),
    isConfidential: boolean().notNull().default(true),
    /** the exam date, after which confidentiality ends */
    opensOn: dateStr(),
    createdByStaffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    approvedBy: uuid().references((): AnyPgColumn => profiles.id),
    approvedAt: timestamptz(),
    /** the paper */
    documentId: uuid().references((): AnyPgColumn => generatedDocuments.id),
    /** the answer key */
    keyDocumentId: uuid().references((): AnyPgColumn => generatedDocuments.id),
  },
  (t) => [
    positive('question_papers', t.totalMarks),
    positive('question_papers', t.durationMinutes),
    index('question_papers_branch_grade_subject_status_idx').on(
      t.orgId,
      t.branchId,
      t.gradeSubjectId,
      t.status,
    ),
    customPolicy('question_papers_confidential', {
      for: 'all',
      restrictive: true,
      using: sql`not (${t.isConfidential} and (${t.opensOn} is null or ${t.opensOn} > (select app.today()))) or (select app.has_cap('papers')) or ${t.createdByStaffId} = (select app.staff_id())`,
      withCheck: sql`not (${t.isConfidential} and (${t.opensOn} is null or ${t.opensOn} > (select app.today()))) or (select app.has_cap('papers')) or ${t.createdByStaffId} = (select app.staff_id())`,
    }),
  ],
);

export const paperSections = defineTable(
  'paper_sections',
  { module: 'M19', scope: 'branch', custom: true },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    questionPaperId: uuid()
      .references((): AnyPgColumn => questionPapers.id)
      .notNull(),
    sortOrder: integer().notNull(),
    /** "Section A: Objective" */
    title: text().notNull(),
    /** "Attempt any five" */
    instructions: text(),
    /** fewer than the questions in the section */
    attemptCount: integer(),
    marksEach: decimal(5, 2),
  },
  (t) => [
    customPolicy('paper_sections_follows_paper', {
      for: 'all',
      restrictive: true,
      using: sql`exists (select 1 from question_papers p where p.id = ${t.questionPaperId})`,
      withCheck: sql`exists (select 1 from question_papers p where p.id = ${t.questionPaperId})`,
    }),
  ],
);

/** A frozen copy of each question as it appears on the paper. */
export const paperQuestions = defineTable(
  'paper_questions',
  { module: 'M19', scope: 'branch', custom: true },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    questionPaperId: uuid()
      .references((): AnyPgColumn => questionPapers.id)
      .notNull(),
    paperSectionId: uuid()
      .references((): AnyPgColumn => paperSections.id)
      .notNull(),
    /** the bank question it came from */
    questionId: uuid().references((): AnyPgColumn => questions.id),
    sortOrder: integer().notNull(),
    /** "Q3", "Q5 (b)" */
    numberLabel: text().notNull(),
    type: text().notNull(),
    text: text().notNull(),
    textUr: text(),
    options: jsonb().notNull().default([]),
    answer: jsonb(),
    marks: decimal(5, 2).notNull(),
    unitId: uuid().references((): AnyPgColumn => syllabusUnits.id),
    outcomeId: uuid().references((): AnyPgColumn => learningOutcomes.id),
    isAiWritten: boolean().notNull().default(false),
    aiAcceptedBy: uuid().references((): AnyPgColumn => profiles.id),
    aiAcceptedAt: timestamptz(),
  },
  (t) => [
    positive('paper_questions', t.marks),
    customPolicy('paper_questions_follows_paper', {
      for: 'all',
      restrictive: true,
      using: sql`exists (select 1 from question_papers p where p.id = ${t.questionPaperId})`,
      withCheck: sql`exists (select 1 from question_papers p where p.id = ${t.questionPaperId})`,
    }),
  ],
);
